{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    required = ("threshold", "calls")
    if any(key not in case for key in required):
        raise ValueError("missing required case field")
    threshold = case["threshold"]
    calls = case["calls"]
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)) or not math.isfinite(threshold):
        raise ValueError("threshold must be a finite number")
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    fields = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")
    for call in calls:
        if not isinstance(call, dict) or any(field not in call for field in fields):
            raise ValueError("missing required call field")
        if not isinstance(call["call_id"], str):
            raise ValueError("call_id must be a string")
        for field in ("loss_without_call", "loss_with_call"):
            value = call[field]
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
                raise ValueError("loss values must be finite numbers")
        tokens = call["prediction_tokens"]
        if isinstance(tokens, bool) or not isinstance(tokens, int) or tokens < 0:
            raise ValueError("prediction_tokens must be a nonnegative integer")
        if not isinstance(call["parseable"], bool):
            raise ValueError("parseable must be boolean")

    diagnostics = []
    accepted_call_ids = []
    for call in calls:
        normalized_gain = (call["loss_without_call"] - call["loss_with_call"]) / max(1, call["prediction_tokens"])
        normalized_gain = round(normalized_gain, 6)
        accepted = call["parseable"] and normalized_gain >= threshold
        diagnostics.append({
            "accepted": accepted,
            "call_id": call["call_id"],
            "normalized_gain": normalized_gain,
        })
        if accepted:
            accepted_call_ids.append(call["call_id"])
    return {"accepted_call_ids": accepted_call_ids, "diagnostics": diagnostics}"}
